"use strict";(self.webpackChunkwww=self.webpackChunkwww||[]).push([[77169],{17751:(e,t,o)=>{o.r(t),o.d(t,{assets:()=>r,contentTitle:()=>a,default:()=>c,frontMatter:()=>h,metadata:()=>i,toc:()=>d});var n=o(31085),s=o(71184);const h={sidebar_position:16,slug:"/bible/Matthew/Matthew_16",title:"Matthew 16",hide_table_of_contents:!0},a="Matthew",i={id:"bible/Matthew/Matthew 16",title:"Matthew 16",description:"Chapter 16",source:"@site/docs/bible/Matthew/Matthew 16.md",sourceDirName:"bible/Matthew",slug:"/bible/Matthew/Matthew_16",permalink:"/bibleNotes/docs/bible/Matthew/Matthew_16",draft:!1,unlisted:!1,editUrl:"https://github.com/ozkey/bibleNotes/tree/main/packages/www/docs/bible/Matthew/Matthew 16.md",tags:[],version:"current",sidebarPosition:16,frontMatter:{sidebar_position:16,slug:"/bible/Matthew/Matthew_16",title:"Matthew 16",hide_table_of_contents:!0},sidebar:"bibleSidebar",previous:{title:"Matthew 15",permalink:"/bibleNotes/docs/bible/Matthew/Matthew_15"},next:{title:"Matthew 17",permalink:"/bibleNotes/docs/bible/Matthew/Matthew_17"}},r={},d=[{value:"Chapter 16",id:"chapter-16",level:2}];function l(e){const t={admonition:"admonition",h1:"h1",h2:"h2",p:"p",...(0,s.R)(),...e.components},{BibleText:o}=t;return o||function(e,t){throw new Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("BibleText",!0),(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.h1,{id:"matthew",children:"Matthew"}),"\n",(0,n.jsx)(t.h2,{id:"chapter-16",children:"Chapter 16"}),"\n",(0,n.jsx)(t.p,{children:"Christ refuses to shew the Pharisees a sign from heaven.  Peter's confession is rewarded.  He is rebuked for opposing Christ's passion. All his followers must deny themselves."}),"\n",(0,n.jsx)(o,{verse:1,children:"And there came to him the Pharisees and Sadducees tempting: and they asked him to shew them a sign from heaven."}),"\n",(0,n.jsx)(o,{verse:2,children:"But he answered and said to them: When it is evening, you say, It will be fair weather, for the sky is red."}),"\n",(0,n.jsx)(o,{verse:3,children:"And in the morning: To day there will be a storm, for the sky is red and lowering. You know then how to discern the face of the sky: and can you not know the signs of the times?"}),"\n",(0,n.jsx)(o,{verse:4,children:"A wicked and adulterous generation seeketh after a sign: and a sign shall not be given it, but the sign of Jonas the prophet. And he left them, and went away."}),"\n",(0,n.jsx)(o,{verse:5,children:"And when his disciples were come over the water, they had forgotten to take bread."}),"\n",(0,n.jsx)(o,{verse:6,children:"Who said to them: Take heed and beware of the leaven of the Pharisees and Sadducees."}),"\n",(0,n.jsx)(o,{verse:7,children:"But they thought within themselves, saying: Because we have taken no bread."}),"\n",(0,n.jsx)(o,{verse:8,children:"And Jesus knowing it, said: Why do you think within yourselves, O ye of little faith, for that you have no bread?"}),"\n",(0,n.jsx)(o,{verse:9,children:"Do you not yet understand, neither do you remember the five loaves among five thousand men, and how many baskets you took up?"}),"\n",(0,n.jsx)(o,{verse:10,children:"Nor the seven loaves, among four thousand men, and how many baskets you took up?"}),"\n",(0,n.jsx)(o,{verse:11,children:"Why do you not understand that it was not concerning bread I said to you: Beware of the leaven of the Pharisees and Sadducees?"}),"\n",(0,n.jsx)(o,{verse:12,children:"Then they understood that he said not that they should beware of the leaven of bread, but of the doctrine of the Pharisees and Sadducees."}),"\n",(0,n.jsx)(o,{verse:13,children:"And Jesus came into the quarters of Cesarea Philippi: and he asked his disciples, saying: Whom do men say that the Son of man is?"}),"\n",(0,n.jsx)(o,{verse:14,children:"But they said: Some John the Baptist, and other some Elias, and others Jeremias, or one of the prophets."}),"\n",(0,n.jsx)(o,{verse:15,children:"Jesus saith to them: But whom do you say that I am?"}),"\n",(0,n.jsx)(o,{verse:16,children:"Simon Peter answered and said: Thou art Christ, the Son of the living God."}),"\n",(0,n.jsx)(o,{verse:17,children:"And Jesus answering said to him: Blessed art thou, Simon Bar-Jona: because flesh and blood hath not revealed it to thee, but my Father who is in heaven."}),"\n",(0,n.jsx)(o,{verse:18,children:"And I say to thee: That thou art Peter; and upon this rock I will build my church, and the gates of hell shall not prevail against it."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: Thou art Peter, etc...As St. Peter, by divine revelation, here made a solemn profession of his faith of the divinity of Christ; so in recompense of this faith and profession, our Lord here declares to him the dignity to which he is pleased to raise him: viz., that he to whom he had already given the name of Peter, signifying a rock, St. John 1. 42, should be a rock indeed, of invincible strength, for the support of the building of the church; in which building he should be, next to Christ himself, the chief foundation stone, in quality of chief pastor, ruler, and governor; and should have accordingly all fulness of ecclesiastical power, signified by the keys of the kingdom of heaven.\r\nNote 2: Upon this rock, etc...The words of Christ to Peter, spoken in the vulgar language of the Jews which our Lord made use of, were the same as if he had said in English, Thou art a Rock, and upon this rock I will build my church. So that, by the plain course of the words, Peter is here declared to be the rock, upon which the church was to be built: Christ himself being both the principal foundation and founder of the same. Where also note, that Christ, by building his house, that is, his church, upon a rock, has thereby secured it against all storms and floods, like the wise builder, St. Matt. 7. 24, 25. The gates of hell,\r\nNote 3: etc...That is, the powers of darkness, and whatever Satan can do, either by himself, or his agents. For as the church is here likened to a house, or fortress, built on a rock; so the adverse powers are likened to a contrary house or fortress, the gates of which, that is, the whole strength, and all the efforts it can make, will never be able to prevail over the city or church of Christ. By this promise we are fully assured, that neither idolatry, heresy, nor any pernicious error whatsoever shall at any time prevail over the church of Christ."})}),"\n",(0,n.jsx)(o,{verse:19,children:"And I will give to thee the keys of the kingdom of heaven. And whatsoever thou shalt bind upon earth, it shall be bound also in heaven: and whatsoever thou shalt loose on earth, it shall be loosed also in heaven."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: Loose on earth...The loosing the bands of temporal punishments due to sins, is called an indulgence; the power of which is here granted."})}),"\n",(0,n.jsx)(o,{verse:20,children:"Then he commanded his disciples, that they should tell no one that he was Jesus the Christ."}),"\n",(0,n.jsx)(o,{verse:21,children:"From that time Jesus began to shew to his disciples, that he must go to Jerusalem, and suffer many things from the ancients and scribes and chief priests, and be put to death, and the third day rise again."}),"\n",(0,n.jsx)(o,{verse:22,children:"And Peter taking him, began to rebuke him, saying: Lord, be it far from thee, this shall not be unto thee."}),"\n",(0,n.jsx)(t.admonition,{type:"note",children:(0,n.jsx)(t.p,{children:"Note 1: And Peter taking him...That is, taking him aside, out of a tender love, respect and zeal for his Lord and Master's honour, began to expostulate with him, as it were to rebuke him, saying, Lord, far be it from thee to suffer death; but the Lord said to Peter, ver. 23, Go behind me, Satan. These words may signify, Begone from me; but the holy Fathers expound them otherwise, that is, come after me, or follow me; and by these words the Lord would have Peter to follow him in his suffering, and not to oppose the divine will by contradiction; for the word satan means in Hebrew an adversary, or one that opposes."})}),"\n",(0,n.jsx)(o,{verse:23,children:"Who turning, said to Peter: Go behind me, Satan, thou art a scandal unto me: because thou savourest not the things that are of God, but the things that are of men."}),"\n",(0,n.jsx)(o,{verse:24,children:"Then Jesus said to his disciples: If any man will come after me, let him deny himself, and take up his cross, and follow me."}),"\n",(0,n.jsx)(o,{verse:25,children:"For he that will save his life, shall lose it: and he that shall lose his life for my sake, shall find it."}),"\n",(0,n.jsx)(o,{verse:26,children:"For what doth it profit a man, if he gain the whole world and suffer the loss of his own soul? Or what exchange shall a man give for his soul?"}),"\n",(0,n.jsx)(o,{verse:27,children:"For the Son of man shall come in the glory of his Father with his angels: and then will he render to every man according to his works."}),"\n",(0,n.jsx)(o,{verse:28,children:"Amen I say to you, there are some of them that stand here, that shall not taste death, till they see the Son of man coming in his kingdom."})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}},71184:(e,t,o)=>{o.d(t,{R:()=>a,x:()=>i});var n=o(14041);const s={},h=n.createContext(s);function a(e){const t=n.useContext(h);return n.useMemo((function(){return"function"==typeof e?e(t):{...t,...e}}),[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),n.createElement(h.Provider,{value:t},e.children)}}}]);